#include SOURCE
#include <chrono>
#include <cstdint>
#include <iostream>
#include <string>
#include <vector>
struct Mod{std::uint32_t v=0;Mod()=default;Mod(std::int64_t x):v(static_cast<std::uint32_t>(x%998244353)){}Mod&operator+=(Mod b){v+=b.v;if(v>=998244353)v-=998244353;return *this;}Mod&operator-=(Mod b){if(v<b.v)v+=998244353;v-=b.v;return *this;}Mod&operator*=(Mod b){v=std::uint64_t(v)*b.v%998244353;return *this;}friend Mod operator+(Mod a,Mod b){return a+=b;}friend Mod operator*(Mod a,Mod b){return a*=b;}friend bool operator==(Mod,Mod)=default;};
template<class T>void run(std::size_t n,int mode,int loops){std::vector<T>a(n),b(n);for(std::size_t i=1;i<n;++i){a[i]=T((i*13+17)%8);b[i]=T((i*41+23)%8);}IntegerSieve sieve(n?static_cast<int>(n-1):0);auto once=[&]{std::vector<T>out;if(mode==0)out=gcd_convolution(a,b,sieve);else if(mode==1)out=lcm_convolution(a,b,sieve);else if(mode==2){out=a;multiple_zeta_transform(out,sieve);multiple_mobius_transform(out,sieve);}else if(mode==3){out=a;divisor_zeta_transform(out,sieve);divisor_mobius_transform(out,sieve);}else if(mode==4){
#ifdef SIRKIT_ZETA_INTEGER_EXTRA
out=gcd_square(a,sieve);
#else
out=gcd_convolution(a,a,sieve);
#endif
}else if(mode==5){
#ifdef SIRKIT_ZETA_INTEGER_EXTRA
out=lcm_square(a,sieve);
#else
out=lcm_convolution(a,a,sieve);
#endif
}else{IntegerSieve table(n?static_cast<int>(n-1):0);return static_cast<std::uint64_t>(table.prime_list.size())+(table.least_prime_factor.empty()?0:table.least_prime_factor.back());}std::uint64_t sum=0;for(auto x:out){if constexpr(std::is_same_v<T,Mod>)sum+=x.v;else sum+=x;}return sum;};auto checksum=once();auto start=std::chrono::steady_clock::now();for(int k=0;k<loops;++k)checksum+=once();const auto end=std::chrono::steady_clock::now();std::cout<<std::chrono::duration<double,std::milli>(end-start).count()<<' '<<checksum<<'\n';}
int main(int argc,char**argv){if(argc!=5)return 1;const auto n=std::stoull(argv[1]);const int mode=std::stoi(argv[2]),loops=std::stoi(argv[3]);if(std::string(argv[4])=="mod")run<Mod>(n,mode,loops);else run<std::uint64_t>(n,mode,loops);}

