from pathlib import Path
import subprocess,json,hashlib,statistics,time,fcntl,sys
p=Path(__file__).parent;r=Path('/home/reinsirk/Atcoder_Env');o=p/'main_performance';o.mkdir(exist_ok=True);sha=lambda b:hashlib.sha256(b).hexdigest();ids={f'zeta_{op}_{kind}_full':op+'_convolution'for op in ['gcd','lcm']for kind in ['conv','transform']};ccs={'gcc':['g++'],'clang':['clang++','--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0']};base=(p/'baseline.hpp').read_bytes();final=(p/'final.hpp').read_bytes();variants={'baseline':base,'control':base,'final':final}
if sys.argv[1]=='build':
 builds=[]
 for id in ids:
  original=(p.parent/'baseline/Verify/current/submissions'/(id+'.cpp')).read_bytes();assert original.count(base)==1
  for v,src in variants.items():
   tu=original.replace(base,src,1);cpp=o/(id+'_'+v+'.cpp');cpp.write_bytes(tu)
   if v=='final':assert tu==(r/'Verify/current/submissions'/(id+'.cpp')).read_bytes()
   for cc,args in ccs.items():
    exe=o/(cc+'_'+id+'_'+v);cmd=['taskset','-c','6',*args,'-std=c++23','-O2',str(cpp),'-o',str(exe)];a=subprocess.run(cmd,capture_output=True,check=True);assert not a.stderr;builds.append(dict(id=id,compiler=cc,variant=v,command=cmd,source_sha256=sha(src),translation_unit_sha256=sha(tu),binary_sha256=sha(exe.read_bytes())))
 (o/'builds.json').write_text(json.dumps(builds,indent=2)+'\n');print('performance builds ready');sys.exit()
builds=json.loads((o/'builds.json').read_text());cases={task:[p/'cases'/task/n for n in ['example_00.in','random_00.in','max_random_00.in','max_random_01.in','near_prime_00.in','near_prime_squared_00.in']]for task in set(ids.values())};refs={(task,f.name):(p/'expected'/task/(f.name+'.out')).read_bytes().split()for task,fs in cases.items()for f in fs};raw={cc:{id:{v:{f.name:[]for f in cases[task]}for v in variants}for id,task in ids.items()}for cc in ccs};outputs={};cache=set()
with open(str(p.parent/'benchmark_zeta.lock'),'a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for rep in range(7):
  for cc in ccs:
   for id,task in ids.items():
    for f in cases[task]:
     names=list(variants);names=names[rep%3:]+names[:rep%3]
     for v in names:
      start=time.perf_counter_ns()
      with f.open('rb')as inp:out=subprocess.check_output(['taskset','-c','14',str(o/(cc+'_'+id+'_'+v))],stdin=inp)
      ms=(time.perf_counter_ns()-start)/1e6;digest=sha(out);key=(task,f.name,digest)
      if key not in cache:assert out.split()==refs[(task,f.name)];cache.add(key)
      raw[cc][id][v][f.name].append(ms);outputs.setdefault(cc,{}).setdefault(id,{}).setdefault(v,{})[f.name]=digest
  print('round',rep,'complete',flush=True)
med={cc:{id:{v:{f:statistics.median(xs)for f,xs in cs.items()}for v,cs in vs.items()}for id,vs in es.items()}for cc,es in raw.items()};ratios={cc:{id:{v:{f:x/vs['baseline'][f]for f,x in cs.items()}for v,cs in vs.items()}for id,vs in es.items()}for cc,es in med.items()};(o/'results.json').write_text(json.dumps(dict(status='PASS',source_sha256=sha(final),builds=builds,raw_ms=raw,medians_ms=med,ratios=ratios,outputs=outputs,repetitions=7,cpu_affinity=14,parent_cpu=4,note='本体だけ置換。同main/VerifyMod998/fastIO/C++23-O2/SKIP/入力。入力生成と独立参照整数列照合は計時外。実行・入出力・破棄を含む。順序回転・同文control・排他。計測時は親CPU4で読取り、別のビルドはCPU6。'),indent=2,ensure_ascii=False)+'\n');print('main measurement PASS')
for cc,es in ratios.items():
 for id,vs in es.items():print(cc,id,{v:{f:round(x,3)for f,x in cs.items()}for v,cs in vs.items()if v!='baseline'})

